-- 01_stage_and_preview.sql
-- Correcao retroativa dos snapshots de 2026-08-27
-- Fonte: aba 'Página7' (fresh, visivel) do arquivo 862f3c3a-27_08_2026.xlsx
-- SigmaK (sum licencas) esperado: 57897 | Sigma engajadas esperado: 40574 | IDs unicos: 4011
-- Este script NAO escreve na tabela real. Apenas cria staging + previews.

CREATE TABLE IF NOT EXISTS stg_snapshot_20260827 (
  accountancy_id text,
  licencas numeric,
  licencas_engajadas numeric,
  estoque numeric,
  percentual_engajamento numeric,
  penetracao numeric,
  cnpjs numeric,
  cnpjs_livres numeric,
  contas_potencial numeric,
  ratio numeric,
  plano text,
  atribuidas numeric,
  percentual_atribuidas numeric
);

TRUNCATE stg_snapshot_20260827;










-- ===== PREVIEWS (nao escrevem em partner_snapshots) =====
-- Estado ATUAL na tabela real para 2026-08-27:
SELECT count(*) AS linhas, sum(licencas) AS soma_licencas, sum(licencas_engajadas) AS soma_engajadas
FROM partner_snapshots WHERE imported_at::date='2026-08-27';

-- Estado do STAGING (o que sera aplicado):
SELECT count(*) AS linhas, sum(licencas) AS soma_licencas, sum(licencas_engajadas) AS soma_engajadas
FROM stg_snapshot_20260827;

-- UNMATCHED: accountancy_ids no staging sem parceiro correspondente (nao entrarao no apply):
SELECT s.accountancy_id FROM stg_snapshot_20260827 s
LEFT JOIN partners p ON trim(p.accountancy_id::text)=trim(s.accountancy_id)
WHERE p.id IS NULL;

-- Contagem de unmatched:
SELECT count(*) AS unmatched FROM stg_snapshot_20260827 s
LEFT JOIN partners p ON trim(p.accountancy_id::text)=trim(s.accountancy_id)
WHERE p.id IS NULL;
